<?php
 namespace Pterodactyl\Services\Dezerx\DiscordBot; use Throwable; use Illuminate\Http\Request; use Pterodactyl\Models\User; use Illuminate\Support\Facades\Log; use Pterodactyl\Models\ApiKey; use Pterodactyl\Models\Dezerx\DiscordBot; use Illuminate\Support\Facades\Facade; use Illuminate\Contracts\Http\Kernel; use Pterodactyl\Models\Dezerx\DiscordBotMember; class ClientApi { public const LOOPBACK = '127.0.0.1'; private ?string $bearer = null; public function __construct(private User $user, private ?int $keyId) { } public static function for(DiscordBotMember $member): self { return new self($member->user, $member->api_key_id); } public static function forBot(DiscordBot $bot): ?self { return $bot->owner === null ? null : new self($bot->owner, $bot->api_key_id); } public function user(): User { return $this->user; } public function usable(): bool { return $this->bearer() !== null; } public function get(string $path, array $query = []): ApiResponse { return $this->send('GET', $path, $query); } public function post(string $path, array $body = []): ApiResponse { return $this->send('POST', $path, [], $body); } public function delete(string $path): ApiResponse { return $this->send('DELETE', $path); } private function send(string $method, string $path, array $query = [], ?array $body = null): ApiResponse { $bearer = $this->bearer(); if ($bearer === null) { return new ApiResponse(401, ['errors' => [['detail' => 'The bot has no API key for this account any more. Turn it back on from the Discord page in the panel.']]], true); } $url = BotConfig::panelUrl('api/client' . ($path === '' || $path === '/' ? '' : '/' . ltrim($path, '/'))); if ($query !== []) { $url .= '?' . http_build_query($query); } $request = Request::create($url, $method, [], [], [], [ 'HTTP_ACCEPT' => 'application/json', 'CONTENT_TYPE' => 'application/json', 'HTTP_AUTHORIZATION' => 'Bearer ' . $bearer, 'HTTP_USER_AGENT' => 'Stark Discord Bot', 'REMOTE_ADDR' => self::LOOPBACK, ], $body === null ? null : json_encode($body, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE)); $app = app(); $previous = $app->bound('request') ? $app->make('request') : null; $auth = $app->make('auth'); $guard = $auth->getDefaultDriver(); $auth->forgetGuards(); try { $response = $app->make(Kernel::class)->handle($request); $status = $response->getStatusCode(); $decoded = json_decode((string) $response->getContent(), true); } catch (Throwable $exception) { Log::warning('discord bot: in-process client API call failed', ['path' => $path, 'error' => $exception->getMessage()]); return new ApiResponse(500, null); } finally { $auth->forgetGuards(); $auth->shouldUse($guard); if ($previous !== null) { $app->instance('request', $previous); Facade::clearResolvedInstance('request'); } } return new ApiResponse($status, is_array($decoded) ? $decoded : null); } private function bearer(): ?string { if ($this->bearer !== null) { return $this->bearer; } $key = $this->keyId === null ? null : ApiKey::query()->find($this->keyId); if ($key === null || (int) $key->user_id !== (int) $this->user->id || (int) $key->key_type !== ApiKey::TYPE_ACCOUNT) { return null; } try { return $this->bearer = $key->identifier . decrypt($key->token); } catch (Throwable) { return null; } } } 